-- Fill address_format and phone_format for all countries.
-- address_format: standard template (identical to the code fallback in
-- catalog/controller/account/order.php), only empty cells are filled.
-- phone_format: libphonenumber primary mobile format per territory (X = one
-- digit, other chars are literal — see help_phone_format). Only territories
-- with a fixed national number length get a mask; variable-length plans
-- (DE, IT, BR, AT, ...) and territories without numbering data (UM, AN)
-- intentionally keep phone_format empty so checkout falls back to the
-- lenient 3-32 digit check instead of rejecting valid numbers.
-- Idempotent: only empty cells are updated, re-running is a no-op.

-- Address formats (base table, empty only)
UPDATE `oc_country` SET `address_format` = '{firstname} {lastname}\r\n{company}\r\n{address_1}\r\n{address_2}\r\n{city} {postcode}\r\n{zone}\r\n{country}'
WHERE `address_format` = '';

-- Phone masks (base table, empty only)
