-- Per-language address formats: inherit base where empty
UPDATE `oc_country_description` cd
JOIN `oc_country` c ON c.`country_id` = cd.`country_id`
SET cd.`address_format` = c.`address_format`
WHERE cd.`address_format` = '' AND c.`address_format` <> '';
